import {readableTerm} from './labels.js';
import {uploadFile} from './upload.js';
import {renderChatText,eventLabel,operationLabel} from './chat-format.js';
export function createConversationUI({api,endpoint,getState,esc,toast,refresh,openDialog,closeDialog}){
 let whatsappInfo=null;
 const $=s=>document.querySelector(s);let companyId='',thread='',threads=[],data={messages:[],events:[],jobs:[]},profiles=[],draft='',mode='execute',attachments=[],approvedMedia=false,submitting=false,currentView='',loading=false,loadSequence=0,selectionVersion=0,loadedThread='',preview='',timer,signature='',pendingSubmission=null;
 const approvedImage=()=>attachments.length===1&&getState().assets.find(a=>a.id===attachments[0])?.mime?.startsWith('image/');
 const threadPending=()=>!!thread&&loadedThread!==thread;
 const active=()=>data.jobs.some(j=>['queued','working'].includes(j.state));
 const glyph='<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="M24 4v40M4 24h40M10 10l28 28M10 38l28-28" stroke="currentColor" stroke-width="1.5"/><circle cx="43" cy="5" r="3" fill="#ff571f"/></svg>';
 const symbols={instagram:'ig',whatsapp:'wa',google:'G',higgsfield:'hf'};

 const opLabel=operationLabel;
 const evidenceUrl=value=>/^https?:\/\//i.test(value||'')?value:'';
 function operationCards(){return [...(data.operations||[])].sort((a,b)=>b.updatedAt-a.updatedAt).slice(0,3).map(op=>{const plan=op.plan||[],done=plan.filter(step=>['completed','done','succeeded'].includes(step.status)).length,deliveries=(op.artifactIds||[]).map(id=>getState().records.content.find(c=>c.id===id)).filter(Boolean),terminal=['completed','learned','cancelled'].includes(op.state);return `<article class="operation-context" data-operation-id="${esc(op.id)}"><div class="operation-context-heading"><span>OPERAÇÃO DA ${esc(getState().company.name)}</span><span class="badge badge-${esc(op.state)}">${esc(op.paused?'Pausada':opLabel(op.state))}</span></div><h2>${esc(op.objective)}</h2>${plan.length?`<p class="operation-progress">${done} de ${plan.length} etapas concluídas${op.competencies?.length?' · '+esc(op.competencies.map(c=>c.name).join(', ')):''}</p>`:''}${(op.blockers||[]).map(b=>`<p class="operation-blocker">${esc(b.message)}</p>`).join('')}${op.state==='uncertain'?'<p class="operation-blocker">O resultado precisa ser verificado no canal. Esta ação não será repetida automaticamente.</p>':''}${deliveries.length?`<div class="operation-deliveries">${deliveries.map(c=>`<button type="button" data-action="content-detail" data-id="${esc(c.id)}">↗ ${esc(c.title)}</button>`).join('')}</div>`:''}${op.result?.summary?`<p class="operation-result">${esc(op.result.summary)}</p>`:''}${op.result?.measurement?`<p class="operation-result">${esc(op.result.measurement)}</p>`:''}<details class="operation-details" data-details-key="${esc(thread+':operation:'+op.id)}"><summary>Plano e registros</summary><ol>${plan.map(step=>`<li><span>${esc(step.title)}</span><small>${esc(opLabel(step.status))}${step.competency?' · '+esc(op.competencies?.find(c=>c.id===step.competency)?.name||step.competency):''}</small></li>`).join('')}</ol>${(op.evidence||[]).length?`<div class="operation-evidence">${op.evidence.map(ev=>`<p><strong>${esc(opLabel(ev.status))}</strong> · ${esc(ev.executor?readableTerm(ev.executor):'Ferramenta')}${ev.channel?' · '+esc(readableTerm(ev.channel)):''}<small>${esc(ev.message||ev.error||'Registro da execução')}${ev.externalId?' · '+esc(ev.externalId):''}${ev.occurredAt?' · '+new Date(ev.occurredAt).toLocaleString('pt-BR'):''}</small>${evidenceUrl(ev.url)?`<a href="${esc(ev.url)}" target="_blank" rel="noopener">Ver evidência ↗</a>`:''}</p>`).join('')}</div>`:'<p class="micro-copy">Nenhuma execução externa comprovada nesta operação.</p>'}<div class="operation-links"><a href="#/studio">Estúdio</a><a href="#/tasks">Tarefas</a>${op.campaignId?'<a href="#/campaigns">Campanha</a>':''}<a href="#/results">Resultados</a></div></details><div class="operation-controls">${op.firstInstagram&&op.state==='uncertain'?`<button class="p-button secondary" data-action="link-publication" data-id="${esc(op.id)}">Vincular publicação encontrada</button>`:''}${op.state==='uncertain'?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="verify">Conferir resultado</button>`:''}${op.state==='completed'?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="measure">Acompanhar resultados</button>`:''}${op.state==='measuring'?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="learn">Registrar aprendizado</button>`:''}${op.state==='awaiting_approval'&&!op.paused?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="approve">Aprovar entregas</button>`:''}${!op.firstInstagram&&deliveries.length>0&&op.state==='ready'&&!op.paused?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="execute">Executar publicação</button><a class="quiet-button" href="#/calendar">Agendar</a>`:''}${op.firstInstagram&&!op.paused&&['blocked','ready','reviewing','awaiting_approval','failed'].includes(op.state)?`<button class="p-button secondary" data-action="select-operation-asset" data-id="${esc(op.id)}">Selecionar mídia aprovada</button>`:''}${op.firstInstagram&&!op.paused&&!['executing','verifying','uncertain','completed','measuring','learned','cancelled'].includes(op.state)?`<button class="p-button secondary" data-action="publication-review" data-id="${esc(op.id)}">Revisar publicação</button>`:''}${!terminal&&op.state!=='uncertain'?(op.paused||['blocked','failed'].includes(op.state)?`<button class="quiet-button" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="resume">Retomar operação</button>`:`<button class="quiet-button" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="pause">Pausar operação</button>`):''}</div></article>`;}).join('');}

 function ensureCompany(){const id=getState()?.company.id||'';if(companyId!==id){companyId=id;whatsappInfo=null;clearThread();threads=[];profiles=[];preview='';}}
 function clearThread(id=''){++selectionVersion;++loadSequence;loading=false;thread=id;loadedThread='';data={messages:[],events:[],jobs:[]};draft='';attachments=[];approvedMedia=false;signature='';pendingSubmission=null;}
 function validateAttachments(ids){
  if(ids.length>8)throw new Error('Adicione até oito referências por mensagem.');
  let bytes=0;for(const id of ids){const asset=getState().assets.find(a=>a.id===id);if(!asset)throw new Error('Uma referência não está disponível nesta empresa.');if(asset.mime?.startsWith('image/')||asset.mime==='application/pdf')bytes+=asset.size||0;}
  if(bytes>20*1024*1024)throw new Error('Use até 20 MB de imagens e PDFs por pedido.');
 }
 function astraStatus(s){const brain=s.integrations.find(c=>c.id==='openai'),ready=brain?.configured&&brain.verifiedAt&&brain.validation?.status==='validated';return '<div class="astra-state"><a class="astra-connection" href="#/integrations"><span class="astra-dot '+(ready?'is-ready':'')+'"></span>'+esc(brain?.values?.agentModel==='gpt-6-astra'||!brain?.values?.agentModel?'GPT-6 Astra':brain.values.agentModel)+' · '+(ready?'conectado':brain?.configured?'validar conexão':'conectar')+'</a><a class="astra-routine" href="#/settings">'+(s.company.policy?.enabled?(s.worker?.running?'Rotina diária ativa':'Rotina aguardando executor'):'Sob demanda')+'</a></div>';}
 function attention(s){const ids=new Set((data.operations||[]).flatMap(op=>op.artifactIds||[]));const p=s.production?.find(p=>ids.has(p.contentId)&&p.blockers?.length);if(!p)return '';return '<details class="chat-attention"><summary>Uma criação precisa de um ajuste para continuar</summary><p>'+esc(p.blockers[0].message)+'</p><button class="quiet-button" data-action="studio-production" data-id="'+esc(p.contentId)+'">Ver o que falta ↗</button></details>';}
 function workingLabel(){const job=data.jobs.find(j=>['queued','working'].includes(j.state));return eventLabel(data.events.filter(e=>e.jobId===job?.id).at(-1));}
 function executionTrail(){return data.events.length?`<details class="execution-trail" data-details-key="${esc(thread+':events')}"><summary>Ver registros da execução</summary><ol>${data.events.slice(-30).map(e=>`<li><span>${e.kind==='completed'?'✓':e.kind==='attention'?'!':'·'}</span><div>${esc(eventLabel(e))}${e.detail?.confirmation?`<small>${esc(e.detail.confirmation)}</small>`:''}</div></li>`).join('')}</ol></details>`:'';}
 function activity(s){const ops=[...(data.operations||[])].sort((a,b)=>b.updatedAt-a.updatedAt);if(!ops.length&&!data.events.length)return '';const needs=ops.find(op=>!op.paused&&['blocked','failed','uncertain','awaiting_approval'].includes(op.state)),latest=needs||ops[0];return `<details class="chat-activity ${needs?'needs-attention':''}" data-details-key="${esc(thread+':activity')}"><summary><strong>Andamento e entregas</strong><span class="chat-activity-status">${latest?esc(latest.paused?'Pausado':opLabel(latest.state)):'Ver detalhes'}</span></summary>${operationCards()}${attention(s)}${executionTrail()}</details>`;}
 function replyError(){const error=data.jobs[0]?.error;if(!error||data.messages.some(m=>m.role==='assistant'&&m.jobId===data.jobs[0].id&&m.text.includes(error)))return '';return '<div class="chat-run-error" role="status">'+esc(error)+'</div>';}
 function messageAttachments(m){return (m.attachments||[]).map(id=>{const a=getState().assets.find(a=>a.id===id);if(!a)return '';const url='/api/portal/files/'+encodeURIComponent(a.id);return a.mime?.startsWith('image/')?`<figure class="chat-image"><a href="${esc(url)}" target="_blank" rel="noopener"><img src="${esc(url)}" alt="${esc(a.name)}" loading="lazy"></a><figcaption>${esc(a.name)} · <a href="${esc(url)}" download>Baixar imagem</a></figcaption></figure>`:a.mime==='video/mp4'?`<figure class="chat-image chat-video"><video controls preload="metadata" src="${esc(url)}" aria-label="${esc(a.name)}"></video><figcaption>${esc(a.name)} · <a href="${esc(url)}" download>Baixar vídeo</a> · <a href="#/video">Abrir Astra Vídeo</a></figcaption></figure>`:`<a class="chat-file-label" href="${esc(url)}" download>${esc(a.name)}</a>`;}).join('');}
 function mediaProgress(){const jobs=data.mediaJobs||[];return jobs.length?'<div class="chat-media-working" role="status"><span class="thinking-dot"></span> '+(jobs.some(j=>j.kind==='video')?'Preparando seu vídeo na nuvem. O arquivo aparecerá aqui quando estiver salvo.':'Preparando sua imagem. Ela aparecerá aqui quando estiver salva.')+'</div>':'';}
 function welcomeNote(value){const welcome=value?.welcome;if(!welcome?.phone)return '';const labels={not_requested:'Telefone salvo no cadastro. Você não solicitou boas-vindas.',queued:'Boas-vindas aguardando envio.',waiting_configuration:'Boas-vindas pendentes: a Helpu ainda precisa habilitar essa mensagem.',accepted:'Boas-vindas aceitas pelo WhatsApp; aguardando confirmação de entrega.',sent:'Boas-vindas enviadas ao WhatsApp.',delivered:'Boas-vindas entregues no WhatsApp.',read:'Boas-vindas recebidas no WhatsApp.',failed:'Não foi possível entregar as boas-vindas. Você pode ativar o WhatsApp pelo portal.',uncertain:'O envio das boas-vindas não foi confirmado e não será repetido automaticamente.',expired:'O prazo das boas-vindas terminou. Você ainda pode ativar o WhatsApp aqui.',suppressed:'Não repetimos as boas-vindas para este telefone.',canceled:'As boas-vindas foram canceladas.'};return '<p class="micro-copy">'+esc(welcome.consent===false&&welcome.state!=='not_requested'?'Autorização de boas-vindas cancelada.':labels[welcome.state]||'Telefone de contato salvo.')+' Receber esta mensagem não ativa a operação.</p>';}
 function whatsappCard(){return welcomeNote(whatsappInfo)+'<div class="chat-whatsapp-card"><div><strong>Leve o Astra para o WhatsApp</strong><p>Peça criações e acompanhe as respostas também pelo seu celular.</p></div><button type="button" class="p-button secondary" data-chat="whatsapp">'+(whatsappInfo?.enabled?'WhatsApp ativo · gerenciar':'Ativar WhatsApp')+'</button>'+(whatsappInfo?.enabled?'<button type="button" class="quiet-button" data-chat="whatsapp-thread">Abrir conversa vinculada</button>':'')+'</div>';}
 async function whatsappDialog(){
  const org=getState().company.id,base=endpoint('whatsapp-chat');
  const value=await api(base);if(getState().company.id!==org)return;whatsappInfo=value;
  openDialog('Ativar WhatsApp',welcomeNote(value)+'<form id="whatsapp-chat-form"><p>Você conversa com a Helpu pelo número <strong>'+esc(value.officialPhone?'+'+value.officialPhone:'a ser configurado')+'</strong>. Suas respostas e materiais ficam na conversa vinculada do painel.</p>'+(!value.configured?'<p class="chat-run-error">O WhatsApp oficial ainda precisa ser conectado pela administração. Você já pode salvar seu telefone.</p>':'')+'<label class="p-field"><span>Seu WhatsApp com DDD</span><input name="phone" type="tel" autocomplete="tel" required maxlength="24" placeholder="(11) 99999-9999" value="'+esc(value.phone)+'"></label><label class="checkline"><input name="enabled" type="checkbox" '+(value.enabled||!value.phone?'checked':'')+'><span>Ativar conversa pelo WhatsApp</span></label><label class="p-field"><span>O que o Astra pode fazer</span><select name="mode"><option value="execute" '+(value.mode==='execute'?'selected':'')+'>Conversar e executar meus pedidos</option><option value="plan" '+(value.mode==='plan'?'selected':'')+'>Somente planejar</option></select></label>'+(thread?'<label class="checkline"><input name="useCurrent" type="checkbox" '+(value.threadId===thread?'checked':'')+'><span>Usar a conversa que está aberta no painel</span></label>':'')+'<label class="checkline"><input name="consent" type="checkbox" '+(value.enabled?'checked':'')+'><span>Autorizo receber as respostas e os materiais desta empresa no meu WhatsApp.</span></label><p class="micro-copy">O número salvo no cadastro ainda precisa de confirmação. As regras de Autonomia continuam valendo. Você pode desativar aqui ou enviar SAIR. Pedidos já em execução devem ser pausados no painel. Um telefone fica vinculado a uma empresa por vez.</p><div id="whatsapp-chat-result" role="status">'+(value.enabled?'Conectado e ativo.':value.pending?'Aguardando a mensagem de confirmação.':'')+(value.deliveryState==='waiting_window'?'<p>Envie uma mensagem à Helpu para receber as próximas respostas.</p>':'')+(value.lastError?'<p>'+esc(value.lastError)+'</p>':'')+'</div><p class="form-error" hidden></p><button class="p-button primary" type="submit">Salvar</button> <button type="button" class="p-button secondary" data-chat="whatsapp">Conferir conexão</button>'+(value.welcome?.consent?'<button type="button" class="quiet-button" data-chat="welcome-revoke">Cancelar autorização de boas-vindas</button>':'')+'</form>');
  $('#whatsapp-chat-form').addEventListener('submit',async event=>{
   event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),error=form.querySelector('.form-error');button.disabled=true;error.hidden=true;
   try{
    if(getState().company.id!==org)return;
    const next=await api(base,'POST',{phone:form.elements.phone.value,enabled:form.elements.enabled.checked,consent:form.elements.consent.checked,mode:form.elements.mode.value,threadId:form.elements.useCurrent?.checked?thread:undefined});
    if(getState().company.id!==org)return;whatsappInfo=next;
    $('#whatsapp-chat-result').innerHTML=next.connectUrl?'<p>Confirme pelo telefone que você informou. O link vale por dez minutos.</p><a class="p-button primary" target="_blank" rel="noopener noreferrer" href="'+esc(next.connectUrl)+'">Confirmar no WhatsApp ↗</a><p class="micro-copy">Depois de enviar a mensagem, clique em Conferir conexão.</p>':esc(next.message||(next.enabled?'WhatsApp ativo.':'Preferência salva. WhatsApp desativado.'));
   }catch(e){error.textContent=e.message;error.hidden=false;}finally{button.disabled=false;}
  });
 }
 function chat(){ensureCompany();const s=getState();return `<section class="conversation-page ${data.messages.length?'has-messages':''}">${astraStatus(s)}<div class="conversation-toolbar"><button class="quiet-button" data-chat="history">Conversas <span>${threads.length||''}</span></button><button class="quiet-button" data-chat="new">+ Nova conversa</button><a class="quiet-button" href="#/company">Minha empresa ↗</a></div>${!data.messages.length?`<div class="conversation-welcome"><div class="helpu-intelligence">${glyph}</div><span class="intelligence-label">HELPU</span><h1>O que vamos fazer pela sua marca?</h1><p>Converse, envie seus arquivos e acompanhe o Astra cuidando dos próximos passos.</p></div>`:`<div class="conversation-thread-head sr-only"><h1>${esc(threads.find(t=>t.id===thread)?.title||'Sua conversa com a Helpu')}</h1></div><div class="chat-transcript" aria-live="polite">${data.messages.map(m=>`<article class="chat-message ${m.role==='user'?'user':'assistant'}" data-message-id="${esc(m.id)}"><div class="message-byline">${m.role==='user'?'Você':'Helpu'}<time>${new Date(m.createdAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</time></div><div class="chat-message-text">${m.role==='user'?esc(m.text):renderChatText(m.text)}</div>${messageAttachments(m)}</article>`).join('')}${replyError()}${active()?`<div class="chat-working" role="status"><span class="thinking-dot"></span><span>${esc(workingLabel())}</span><button data-chat="stop">Pausar</button></div>`:''}</div>`}${mediaProgress()}${activity(s)}<form id="conversation-composer" class="conversation-composer"><label class="sr-only" for="conversation-prompt">Converse com a Helpu</label><textarea id="conversation-prompt" placeholder="Peça uma criação, organize a semana ou envie um arquivo…" rows="2" required maxlength="16000">${esc(draft)}</textarea>${attachments.length?`<div class="chat-attachments">${attachments.map(id=>`<button type="button" data-chat="remove-attachment" data-id="${id}">${esc(s.assets.find(a=>a.id===id)?.name||'Arquivo')} ×</button>`).join('')}</div>`:''}${approvedImage()?`<label class="approved-media-choice"><input id="conversation-approved-media" type="checkbox" ${approvedMedia?'checked':''}><span>Confirmo que esta é a mídia aprovada para a publicação.<small>A publicação ainda exige a revisão da conta e da legenda e sua aprovação final.</small></span></label>`:''}<div class="composer-controls"><button type="button" class="attach-button" data-chat="attach"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m8 14 7-7a2 2 0 0 1 3 3l-9 9a4 4 0 0 1-6-6L14 2a6 6 0 0 1 8 8L11 21"/></svg>Adicionar arquivo</button><div><label class="composer-mode"><span class="sr-only">Modo da conversa</span><select id="conversation-mode"><option value="execute" ${mode==='execute'?'selected':''}>Conversar e executar</option><option value="plan" ${mode==='plan'?'selected':''}>Somente planejar</option></select></label><button type="submit" class="send-prompt" aria-label="Enviar pedido" ${submitting||active()||threadPending()?'disabled':''}>↑</button></div></div><small class="composer-hint">Enter para enviar · Shift + Enter para quebrar a linha</small></form>${!data.messages.length?`<div class="conversation-suggestions"><button data-chat="suggest" data-text="Vamos estruturar o posicionamento e o plano de marketing da minha empresa."><span>✧</span>Planejar a semana</button><button data-chat="suggest" data-text="Quero criar uma campanha. Vamos definir objetivo, público, oferta e peças."><span>↗</span>Criar campanha</button><a class="p-button secondary" href="#/create/feed"><span>▧</span>Criar imagem</a><a class="p-button secondary" href="#/create/reels"><span>▷</span>Criar Reels</a></div>`:''}${whatsappCard()}${!s.integrations.some(i=>i.id==='openai'&&i.configured)?`<p class="conversation-connection-note"><a href="#/integrations">Conecte a inteligência</a> para receber respostas e executar pedidos.</p>`:''}</section>`;}
 function connectionLabel(p){return {disconnected:p.saved?'Perfil preservado · desconectado':'Não conectado',authentication_required:'Login necessário',identity_unconfirmed:'Identidade não confirmada',identity_confirmed:'Identidade confirmada',identity_declared:'Conta informada por você',uncertain:'Resultado incerto'}[p.connectionState]||(p.open?'Navegador aberto':p.saved?'Perfil preservado':'Não conectado');}
 function connectionIdentity(p){const identity=p.identity||p.validation?.identity;return `${identity?`<p class="session-identity">${esc(identity.username?'@'+identity.username.replace(/^@/,''):identity.accountLabel||p.accountLabel||'Identidade registrada')}${identity.accountId||identity.id?'<small>ID: '+esc(identity.accountId||identity.id)+'</small>':''}</p>`:''}${p.executorAvailable===false?'<p class="session-attention">O perfil permite login e conferência. Publicar por este navegador ainda não foi validado. Use uma API validada para executar a publicação.</p>':''}`;}
 function accounts(){ensureCompany();if(getState()?.worker?.local===false)return '<section class="accounts-page"><div class="page-heading"><div><p class="overline">CONEXÕES</p><h1>Conecte seus canais pela internet.</h1><p>As sessões deste navegador são um recurso da versão local. Na versão online, use as conexões oficiais dos serviços.</p></div></div><a class="p-button primary" href="#/integrations">Abrir conexões</a></section>';return `<section class="accounts-page"><div class="page-heading"><div><p class="overline">CONTAS CONECTADAS</p><h1>O seu navegador faz parte da equipe.</h1><p>Abra a sessão, faça login e confirme a identidade da conta desta empresa.</p></div><a class="p-button secondary" href="#/integrations">Conexões por API</a></div><div class="account-session-grid">${profiles.filter(p=>p.id!=='higgsfield').map(p=>`<article class="session-card"><div class="session-card-heading"><span class="service-monogram">${symbols[p.id]}</span><span class="session-state ${p.open?'is-open':''}">${esc(connectionLabel(p))}</span></div><h2>${esc(p.name)}</h2><p>${p.accountLabel?esc(p.accountLabel):'Sua conta, em uma sessão exclusiva desta empresa.'}</p>${connectionIdentity(p)}${p.uncertainNote?`<p class="session-attention">${esc(p.uncertainNote)}</p>`:''}${p.challenge?'<p class="session-attention">Conclua o login ou a confirmação no navegador.</p>':''}<small>${p.confirmedAt?'Conta confirmada por você · '+new Date(p.confirmedAt).toLocaleDateString('pt-BR'):'A abertura do navegador ainda não confirma o login.'}</small><div class="session-actions"><button class="p-button ${p.open?'secondary':'primary'}" data-chat="open-session" data-id="${p.id}">${p.open?'Abrir janela':'Conectar com login'}</button>${p.open?`<button class="p-button ghost" data-chat="confirm-session" data-id="${p.id}">Confirmar conta</button><button class="p-button ghost" data-chat="preview" data-id="${p.id}">Ver sessão</button>`:''}</div><label class="session-autonomy"><input type="checkbox" disabled ${p.automationAllowed&&p.executorAvailable!==false?'checked':''}>${p.executorAvailable===false?'Executor de publicação ainda não validado':p.automationAllowed?'Operação permitida nesta sessão':'Confirme a conta para permitir a operação'}</label></article>`).join('')||'<p class="padded">Carregando suas conexões…</p>'}</div>${preview?`<section class="browser-preview"><div><h2>${esc(profiles.find(p=>p.id===preview)?.name||'Navegador')} · sessão ao vivo</h2><button class="quiet-button" data-chat="hide-preview">Fechar prévia ×</button></div><img id="session-preview" src="${endpoint('browser/'+preview+'/preview')}?t=${Date.now()}" alt="Prévia da sessão conectada"><p>Para fazer login ou assumir o controle, use a janela aberta no seu computador. A prévia é ocultada durante a autenticação.</p></section>`:''}<div class="account-architecture-note"><h3>Uma inteligência. Mais de uma forma de trabalhar.</h3><p>A Helpu pode usar as APIs disponíveis e operar as sessões que você autorizar. Os perfis ficam neste computador, separados por empresa. Login e autenticação em duas etapas são feitos por você.</p><details><summary>Usar o Chrome que já está aberto</summary><p>O Chrome também oferece uma conexão supervisionada ao navegador existente. Esse caminho exige habilitar a depuração e aceitar a conexão no próprio Chrome. O adaptador para esse modo será separado das sessões dedicadas já disponíveis aqui.</p><a href="https://developer.chrome.com/blog/chrome-devtools-mcp-debug-your-browser-session" target="_blank" rel="noopener">Como funciona no Chrome ↗</a></details></div></section>`;}
 function paint(){
  if(!['conversation','browser'].includes(currentView))return;
  const prompt=$('#conversation-prompt'),focused=document.activeElement===prompt,start=prompt?.selectionStart,end=prompt?.selectionEnd;
  const open=new Set([...document.querySelectorAll('details[data-details-key][open]')].map(el=>el.dataset.detailsKey));
  $('#workspace').innerHTML=currentView==='conversation'?chat():accounts();bind();
  for(const el of document.querySelectorAll('details[data-details-key]'))el.open=open.has(el.dataset.detailsKey);
  if(focused){$('#conversation-prompt')?.focus({preventScroll:true});$('#conversation-prompt')?.setSelectionRange(start,end);}
 }
 async function load({repaint=true}={}){
  ensureCompany();const org=getState()?.company.id;if(!org)return;
  const requestedThread=thread,sequence=++loadSequence,base='/api/portal/'+org+'/';loading=true;
  const current=()=>sequence===loadSequence&&getState()?.company.id===org&&thread===requestedThread;
  try{
   const [ts,bs,next,wa]=await Promise.all([api(base+'conversations'),currentView==='browser'?api(base+'browser'):Promise.resolve({profiles:[]}),requestedThread?api(base+'conversations/'+requestedThread):Promise.resolve(null),api(base+'whatsapp-chat')]);
   if(!current())return;
   const whatsappChanged=JSON.stringify(whatsappInfo)!==JSON.stringify(wa);
   const profilesChanged=JSON.stringify(profiles)!==JSON.stringify(bs.profiles),threadsChanged=JSON.stringify(threads)!==JSON.stringify(ts.conversations),sig=next?JSON.stringify(next):'',changed=next&&sig!==signature;
   if(changed){await refresh(false);if(!current())return;}
   threads=ts.conversations;profiles=bs.profiles;whatsappInfo=wa;
   if(next){data=next;signature=sig;loadedThread=requestedThread;}
   if(repaint&&(changed||profilesChanged||threadsChanged||whatsappChanged||!requestedThread))paint();
  }catch(e){if(current())toast(e.message,true);}finally{if(sequence===loadSequence)loading=false;}
 }
 function mount(view){currentView=view;if(!['conversation','browser'].includes(view))return;bind();load({repaint:true});if(!timer)timer=setInterval(()=>{if(document.hidden||!['conversation','browser'].includes(currentView))return;if(currentView==='browser'&&preview){const img=$('#session-preview');if(img)img.src=endpoint('browser/'+preview+'/preview')+'?t='+Date.now();}if(!submitting&&!loading)load({repaint:true});},3500);}
 function bind(){const prompt=$('#conversation-prompt');prompt?.addEventListener('input',e=>draft=e.target.value);prompt?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();if(draft.trim()&&!submitting&&!active()&&!threadPending())$('#conversation-composer')?.requestSubmit();}});$('#conversation-approved-media')?.addEventListener('change',e=>approvedMedia=e.target.checked);$('#conversation-mode')?.addEventListener('change',e=>mode=e.target.value);$('#conversation-composer')?.addEventListener('submit',send);$('#session-preview')?.addEventListener('error',e=>{e.target.alt='Prévia indisponível durante login, confirmação ou janela fechada. Use Abrir janela.';});}
 function send(e){e.preventDefault();if(submitting||active()||threadPending()||!draft.trim())return;try{validateAttachments(attachments);}catch(error){toast(error.message,true);return;}return submit();async function submit(){submitting=true;const selectedVersion=selectionVersion,org=getState().company.id,rawText=draft,text=draft+(approvedMedia&&approvedImage()?'\n\nA imagem anexada é a mídia aprovada para esta publicação.':''),sendMode=mode,sendAttachments=[...attachments],base='/api/portal/'+org+'/';try{if(!thread){const created=await api(base+'conversations','POST',{title:text.trim().slice(0,70)});if(getState()?.company.id!==org||selectedVersion!==selectionVersion)return;thread=created.id;}const currentThread=thread,fingerprint=JSON.stringify([org,currentThread,text,sendMode,sendAttachments]);if(pendingSubmission?.fingerprint!==fingerprint)pendingSubmission={fingerprint,key:crypto.randomUUID()};await api(base+'conversations/'+currentThread+'/messages','POST',{text,mode:sendMode,attachments:sendAttachments,idempotencyKey:pendingSubmission.key});if(getState()?.company.id!==org||thread!==currentThread||selectedVersion!==selectionVersion)return;pendingSubmission=null;if(draft===rawText){draft='';attachments=[];approvedMedia=false;}await load({repaint:false});paint();}catch(error){toast(error.message,true);}finally{submitting=false;paint();}}}
 function learnOperation(id){openDialog('Registrar aprendizado',`<form id="operation-learning-form"><p class="dialog-explainer">Registre uma observação fundamentada nas medições reais desta campanha. O aprendizado ficará em Marca e negócio, com suas fontes.</p><label class="p-field"><span>O que as medições mostram?</span><textarea name="note" required maxlength="12000" rows="4"></textarea></label><p class="form-error" role="alert" hidden></p><button type="submit" class="p-button primary">Salvar aprendizado</button></form>`);$('#operation-learning-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),error=form.querySelector('.form-error');button.disabled=true;error.hidden=true;try{await api(endpoint('operations/'+id+'/action'),'POST',{action:'learn',note:form.elements.note.value});await refresh(false);await load();closeDialog();toast('Aprendizado registrado com as fontes.');}catch(e){error.textContent=e.message;error.hidden=false;}finally{button.disabled=false;}});}
 function history(){openDialog('Suas conversas',`<div class="chat-history-list">${threads.map(t=>`<button data-chat="choose-thread" data-id="${t.id}"><strong>${esc(t.title)}</strong><small>${new Date(t.updatedAt).toLocaleString('pt-BR')}</small></button>`).join('')||'<p>Sua primeira conversa começa com um objetivo.</p>'}</div>`);}
 function attachmentDialog(){const assets=getState().assets;openDialog('Adicionar uma referência',`<p class="dialog-explainer">Os arquivos ficam na biblioteca da sua empresa. A Helpu pode analisar as imagens e os PDFs anexados ao pedido. Vídeos e músicas ficam disponíveis para edição. A análise visual usa amostras; não transcreve áudio. Use até 20 MB de imagens e PDFs por mensagem.</p><div class="chat-history-list">${assets.map(a=>`<button data-chat="choose-attachment" data-id="${a.id}">${esc(a.name)}<small>${esc(a.mime)}</small></button>`).join('')||'<p>Nenhum arquivo na biblioteca.</p>'}</div><button class="p-button secondary" data-chat="upload-reference">Enviar arquivo</button><input id="conversation-file" type="file" accept="image/png,image/jpeg,image/webp,video/mp4,audio/mpeg,audio/wav,audio/ogg,application/pdf" hidden>`);$('#conversation-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const uploadOrg=getState().company.id,uploadThread=thread;try{if(attachments.length>=8)throw new Error('Adicione até oito referências por mensagem.');const total=attachments.reduce((n,id)=>{const a=getState().assets.find(a=>a.id===id);return n+(a&&(a.mime.startsWith('image/')||a.mime==='application/pdf')?a.size:0);},0);if((file.type.startsWith('image/')||file.type==='application/pdf')&&total+file.size>20*1024*1024)throw new Error('Use até 20 MB de imagens e PDFs por pedido.');if(file.size>25*1024*1024)throw new Error('Envie arquivos de até 25 MB.');const result=await uploadFile(endpoint('files'),file);if(getState().company.id!==uploadOrg||thread!==uploadThread)return;await refresh(false);if(getState().company.id!==uploadOrg||thread!==uploadThread)return;validateAttachments([...attachments,result.id]);attachments.push(result.id);approvedMedia=false;closeDialog();paint();}catch(error){toast(error.message,true);}});}
 function confirmSession(id){const p=profiles.find(x=>x.id===id);openDialog('Confirmar conta · '+p.name,`<form id="confirm-browser-form">${p.uncertainNote?`<div class="chat-run-error">${esc(p.uncertainNote)}</div><label class="checkline"><input name="reviewed" type="checkbox" required><span>Conferi o resultado da última ação diretamente na conta.</span></label>`:''}<p class="dialog-explainer">Confira a conta na janela do navegador. O login e os códigos são preenchidos diretamente no site.</p><label class="p-field"><span>Nome, @perfil ou telefone da conta aberta</span><input name="accountLabel" value="${esc(p.accountLabel)}" required maxlength="120"></label><label class="checkline"><input name="automationAllowed" type="checkbox" ${p.automationAllowed?'checked':''}><span>Permitir que a Helpu opere esta sessão para executar os meus pedidos.</span></label><p class="form-error" hidden></p><button type="submit" class="p-button primary">Confirmar esta conta</button></form>`);$('#confirm-browser-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,button=f.querySelector('button'),error=f.querySelector('.form-error');button.disabled=true;try{await api(endpoint('browser/'+id+'/confirm'),'POST',{accountLabel:f.elements.accountLabel.value,automationAllowed:f.elements.automationAllowed.checked,reviewed:f.elements.reviewed?.checked===true});closeDialog();await load();toast('Conta confirmada na sua empresa.');}catch(err){error.textContent=err.message;error.hidden=false;}finally{button.disabled=false;}});}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-chat]');if(!b)return;const a=b.dataset.chat,id=b.dataset.id;try{
  if(a==='whatsapp'){await whatsappDialog();}
  else if(a==='welcome-revoke'){await api(endpoint('whatsapp-welcome'),'POST',{action:'revoke'});await whatsappDialog();toast('Autorização de boas-vindas cancelada.');}
  else if(a==='whatsapp-thread'){if(whatsappInfo?.threadId){clearThread(whatsappInfo.threadId);paint();await load();}}
  else if(a==='suggest'){draft=b.dataset.text;paint();$('#conversation-prompt')?.focus();}
  else if(a==='new'){clearThread();paint();}
  else if(a==='history')history();else if(a==='choose-thread'){clearThread(id);closeDialog();paint();await load();}
  else if(a==='attach')attachmentDialog();else if(a==='choose-attachment'){if(attachments.length>=8)throw new Error('Adicione até oito referências por mensagem.');if(!attachments.includes(id)){validateAttachments([...attachments,id]);attachments.push(id);approvedMedia=false;}closeDialog();paint();}else if(a==='remove-attachment'){attachments=attachments.filter(x=>x!==id);approvedMedia=false;paint();}else if(a==='upload-reference')$('#conversation-file').click();
  else if(a==='operation-action'){if(b.dataset.operationAction==='learn'){learnOperation(id);return;}b.disabled=true;await api(endpoint('operations/'+id+'/action'),'POST',{action:b.dataset.operationAction});await refresh(false);await load();toast('Operação atualizada.');}
  else if(a==='stop'){await api(endpoint('conversations/'+thread+'/stop'),'POST',{});toast('Pausa solicitada. A etapa em andamento será registrada.');}
  else if(a==='open-session'){b.disabled=true;await api(endpoint('browser/'+id+'/open'),'POST',{});await load();toast('Faça login na janela do navegador e confirme a conta.');}
  else if(a==='confirm-session')confirmSession(id);else if(a==='preview'){preview=id;paint();}else if(a==='hide-preview'){preview='';paint();}
 }catch(error){toast(error.message,true);}finally{b.disabled=false;}});
 return {chat,accounts,mount,reload:()=>load(),async selectThread(id){ensureCompany();clearThread(id);paint();await load();},reset(){companyId='';clearThread();threads=[];profiles=[];preview='';}};
}
